              <th hlmTableHead class="heroes__numeric">Power</th>
              <th hlmTableHead>Status</th>
              <th hlmTableHead>Clearance</th>
              <th hlmTableHead class="heroes__numeric">Actions</th>
            </tr>
          </thead>
          <tbody hlmTableBody>
            @for (row of vm.rows(); track row.hero.id) {
              <tr hlmTableRow>
                <td hlmTableCell>
                  <div class="heroes__identity">
                    <hlm-avatar size="sm">
                      <span hlmAvatarFallback>{{ row.initials }}</span>
